// Audit of a skill generated by spec2skill: `node scripts/audit.mjs <skill dir>` prints one line per
// check and ends with `audit passed`, or exits 1 with the reasons. `auditTree(files)` is the pure part,
// shared with the spec2skill web app and CLI. Plain ESM for Node.js 20+, no dependencies.

const MAX_BODY_LINES = 200;
const MIN_EVALS = 5;

function json(text) {
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
}

/** The YAML subset SKILL.md frontmatter uses: `key: value` (plain or JSON-quoted) and one nested map. */
function frontmatter(md = '') {
  const match = /^---\n([\s\S]*?)\n---\n/.exec(md);
  if (!match) return undefined;
  const data = {};
  let nested;
  for (const line of match[1].split('\n')) {
    const m = /^( {2})?([a-z][a-z0-9-]*):(?: (.*))?$/.exec(line);
    if (!m) return undefined;
    const value = m[3]?.startsWith('"') ? json(m[3]) : m[3];
    if (m[3] && value === undefined) return undefined;
    if (m[1] && nested) nested[m[2]] = value;
    else if (value === undefined) data[m[2]] = nested = {};
    else [data[m[2]], nested] = [value, undefined];
  }
  return { data, body: md.slice(match[0].length) };
}

/** How docs show an operation id: a code span, backticks in the id written as `'`. */
const span = (id) => `\`${String(id).replaceAll('`', "'")}\``;
/** `text` mentions `id` as a whole word. */
const mentions = (text, id) => new RegExp(`(^|[^\\w])${id.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w])`).test(text);
const exampleDirs = (files) => [...new Set(Object.keys(files).flatMap((p) => /^(examples\/[^/]+\/)run\.mjs$/.exec(p)?.[1] ?? []))].toSorted();
/** The operation ids in kit/operations.json (empty when it is missing or broken). */
export const operationIds = (files) => (json(files['kit/operations.json'] ?? '')?.operations ?? []).map((op) => op.id);

function frontmatterProblem(fm) {
  if (!fm) return 'SKILL.md has no parseable frontmatter (--- block of key: value lines)';
  const { name, description, license, compatibility } = fm.data;
  if (typeof name !== 'string' || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(name) || name.length > 64) return 'name must be kebab-case, at most 64 characters';
  if (typeof description !== 'string' || !description || description.length > 1024) return 'description must be 1-1024 characters';
  if (!description.includes('Use when')) return 'description must say when to use the skill ("Use when ...")';
  if (!license || !compatibility) return `missing ${license ? 'compatibility' : 'license'}`;
  return undefined;
}

function evalsProblem(files, ids) {
  const doc = json(files['evals/evals.json'] ?? '');
  if (!Array.isArray(doc?.evals)) return 'evals/evals.json is missing or has no "evals" array';
  if (doc.evals.length < MIN_EVALS) return `only ${doc.evals.length} evals (need at least ${MIN_EVALS})`;
  const seen = new Set();
  for (const e of doc.evals) {
    if (typeof e.id !== 'string' || seen.has(e.id)) return `eval id ${JSON.stringify(e.id)} is missing or repeated`;
    seen.add(e.id);
    if (typeof e.prompt !== 'string' || !e.prompt.trim() || typeof e.expected_output !== 'string' || !e.expected_output.trim()) return `${e.id}: empty prompt or expected_output`;
    if (!Array.isArray(e.files)) return `${e.id}: "files" must be an array`;
    if (!ids.some((id) => mentions(e.expected_output, id))) return `${e.id}: expected_output names no known operation`;
  }
  return undefined;
}

/** Pure checks over `{ path: content }`: `{ ok, checks: [{ id, label, ok, reason? }] }`. */
export function auditTree(files) {
  const checks = [];
  const check = (id, label, reason) => checks.push({ id, label, ok: !reason, ...(reason && { reason }) });
  const skill = files['SKILL.md'];
  const fm = frontmatter(skill);
  check('frontmatter', 'SKILL.md frontmatter: name, description with "Use when", license, compatibility', frontmatterProblem(fm));
  const lines = fm?.body.split('\n').length ?? 0;
  check('body', `SKILL.md body is at most ${MAX_BODY_LINES} lines`, lines > MAX_BODY_LINES ? `body has ${lines} lines` : undefined);

  const ids = operationIds(files);
  const docs = Object.entries(files).filter(([p]) => p === 'SKILL.md' || /^references\/[^/]+\.md$/.test(p)).map(([, t]) => t).join('\n');
  const unreferenced = ids.filter((id) => !docs.includes(span(id)));
  check('operations', 'every operation in kit/operations.json appears in SKILL.md or references/',
    !ids.length ? 'kit/operations.json is missing or lists no operations' : unreferenced.length ? `not referenced: ${unreferenced.slice(0, 5).join(', ')}` : undefined);

  const broken = [];
  for (const [path, text] of Object.entries(files).filter(([p]) => p.endsWith('.md'))) {
    for (const [, target] of text.matchAll(/(?<!\\)\]\(([^)\s]+)\)/g)) {
      if (/^([a-z]+:|#)/i.test(target)) continue;
      const resolved = new URL(target.split('#')[0], `file:///skill/${path}`).pathname.replace(/^\/skill\//, '');
      if (!(resolved in files) && !Object.keys(files).some((p) => p.startsWith(`${resolved.replace(/\/$/, '')}/`))) broken.push(`${path} -> ${target}`);
    }
  }
  check('links', 'every relative link in the Markdown files resolves', broken.length ? `broken: ${broken.slice(0, 5).join(', ')}` : undefined);
  const unlinked = Object.keys(files).filter((p) => /^references\/[^/]+\.md$/.test(p) && !skill?.includes(`](${p})`));
  check('references', 'every references/*.md is linked from SKILL.md', unlinked.length ? `not linked: ${unlinked.join(', ')}` : undefined);

  const kit = ['kit/args.mjs', 'kit/chains.mjs', 'scripts/audit.mjs', 'scripts/audit.test.mjs', 'scripts/kit.test.mjs'];
  const missing = kit.filter((p) => !(p in files)).concat('kit/client.mjs' in files || 'kit/mcp.mjs' in files ? [] : ['kit/client.mjs or kit/mcp.mjs']);
  check('kit', 'kit code and regression tests are present', missing.length ? `missing: ${missing.join(', ')}` : undefined);
  const examples = exampleDirs(files);
  check('examples', 'at least 2 worked examples (examples/*/run.mjs)', examples.length < 2 ? `found ${examples.length}` : undefined);
  check('evals', `evals/evals.json: at least ${MIN_EVALS} well-formed evals naming known operations`, evalsProblem(files, ids));
  const ci = files['ci/github-workflow.yml'];
  const notRun = [...examples.map((d) => `${d}run.mjs`), 'scripts/audit.mjs'].filter((p) => !ci?.includes(p));
  check('ci', 'ci/github-workflow.yml runs the tests, every example and the audit',
    ci === undefined ? 'ci/github-workflow.yml is missing' : notRun.length ? `does not run ${notRun.join(', ')}` : undefined);
  return { ok: checks.every((c) => c.ok), checks };
}

// Node only from here: loaded lazily so the web app can import auditTree.
const node = (name) => import(/* @vite-ignore */ `node:${name}`);

/** Every text file under `dir` as `{ relative path: content }` (skips .git and node_modules). */
export async function readTree(dir) {
  const [{ readdirSync, readFileSync, statSync }, { join, sep }] = await Promise.all([node('fs'), node('path')]);
  const paths = readdirSync(dir, { recursive: true }).map((p) => String(p).split(sep).join('/'));
  return Object.fromEntries(paths.filter((p) => !/(^|\/)(\.git|node_modules)(\/|$)/.test(p) && statSync(join(dir, p)).isFile()).toSorted().map((p) => [p, readFileSync(join(dir, p), 'utf8')]));
}

/** The line of a failed run that says what went wrong: the first `...Error` line, else the first that is not a stack frame. */
export function crashReason(error) {
  const lines = (String(error.stderr ?? '').trim() || String(error.message ?? '')).split('\n').map((l) => l.trim()).filter(Boolean);
  return lines.find((l) => /^\w*Error\b/.test(l)) ?? lines.find((l) => !l.startsWith('at ') && !l.startsWith('Node.js v')) ?? 'no output';
}

/** auditTree plus running each example as a dry run and validating the plan.json it writes. */
export async function auditDir(skillDir) {
  const [{ execFileSync }, { readFileSync }, { join, resolve }] = await Promise.all([node('child_process'), node('fs'), node('path')]);
  // Absolute once: the examples run with the skill as their cwd, so a relative dir must not apply twice.
  const dir = resolve(skillDir);
  const files = await readTree(dir);
  const result = auditTree(files);
  const ids = operationIds(files);
  const failed = [];
  for (const example of exampleDirs(files)) {
    try {
      execFileSync(process.execPath, [join(dir, example, 'run.mjs'), '--dry-run'], { cwd: dir, stdio: 'pipe', timeout: 30_000 });
      const plan = json(readFileSync(join(dir, example, 'plan.json'), 'utf8'));
      const bad = !Array.isArray(plan?.steps) || !plan.steps.length || plan.mode !== 'dry-run' ? 'no dry-run steps' : plan.steps.find((s) => !ids.includes(s.op))?.op;
      if (bad) failed.push(`${example}: ${bad === 'no dry-run steps' ? bad : `unknown operation ${bad}`} in plan.json`);
    } catch (error) {
      failed.push(`${example}run.mjs failed: ${crashReason(error)}`);
    }
  }
  result.checks.push({ id: 'examples-run', label: 'every example runs as a dry run and writes a valid plan.json', ok: !failed.length, ...(failed.length && { reason: failed.join('; ') }) });
  result.ok = result.checks.every((c) => c.ok);
  return result;
}

async function main(dir = '.') {
  const { ok, checks } = await auditDir(dir);
  for (const c of checks) console.log(c.ok ? `ok    ${c.label}` : `FAIL  ${c.label}: ${c.reason}`);
  console.log(ok ? 'audit passed' : `audit failed: ${checks.filter((c) => !c.ok).length} of ${checks.length} checks`);
  process.exitCode = ok ? 0 : 1;
}

/** Run as a script (also through a symlink or from a path with `#` or spaces), not imported. */
async function isMain() {
  const [{ realpathSync }, { fileURLToPath }] = await Promise.all([node('fs'), node('url')]);
  try {
    return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(process.argv[1]);
  } catch {
    return false;
  }
}

if (globalThis.process?.argv?.[1] && import.meta.url.startsWith('file:')) {
  isMain().then((yes) => yes && main(process.argv[2]));
}
